                    transitions[state].append((grid_world["grid"][i-1][j], 1, -1))
                if j > 0 and grid_world["grid"][i][j-1] != "X":
                    transitions[state].append((grid_world["grid"][i][j-1], 1, -1))
                if i < len(grid_world["grid"]) - 1 and grid_world["grid"][i+1][j] != "X":
                    transitions[state].append((grid_world["grid"][i+1][j], 1, -1))
                if j < len(grid_world["grid"][i]) - 1 and grid_world["grid"][i][j+1] != "X":
                    transitions[state].append((grid_world["grid"][i][j+1], 1, -1))
                if state == goal_state:
